{
  "mechanisms": [
    {
      "name": "mb_mf_mixture",
      "title": "MB/MF Mixture Weight",
      "description": "Weights the model-based and model-free stage 1 values to compute a net action value.",
      "params": [
        {
          "name": "w",
          "bounds": [
            0,
            1
          ]
        }
      ],
      "evidence": "q_stage1_net = w * q_stage1_mb + (1 - w) * q_stage1_mf",
      "expressible_in_slots": true
    },
    {
      "name": "choice_perseveration",
      "title": "Choice Perseveration",
      "description": "Adds a stickiness bonus to the stage 1 logit of the action chosen on the previous trial.",
      "params": [
        {
          "name": "pers",
          "bounds": [
            -5,
            5
          ]
        }
      ],
      "evidence": "if last_action != -1:\n            logits_1[last_action] += pers",
      "expressible_in_slots": true
    },
    {
      "name": "eligibility_trace",
      "title": "Eligibility Trace",
      "description": "Updates the stage 1 model-free value of the chosen action using the stage 2 reward prediction error.",
      "params": [
        {
          "name": "lam",
          "bounds": [
            0,
            1
          ]
        }
      ],
      "evidence": "q_stage1_mf[action_1[trial]] += learning_rate * lam * delta_stage2",
      "expressible_in_slots": true
    },
    {
      "name": "unchosen_value_decay",
      "title": "Unchosen Value Decay",
      "description": "Passively decays the values of all unchosen actions at both stages towards 0.5.",
      "params": [
        {
          "name": "decay",
          "bounds": [
            0,
            1
          ]
        }
      ],
      "evidence": "unchosen_1 = 1 - action_1[trial]\n        q_stage1_mf[unchosen_1] += decay * (0.5 - q_stage1_mf[unchosen_1])\n        \n        for s in range(2):\n            for a in range(2):\n                if not (s == state_idx and a == action_2[trial]):\n                    q_stage2_mf[s, a] += decay * (0.5 - q_stage2_mf[s, a])",
      "expressible_in_slots": true
    }
  ]
}
